var DX_BODY = window.DX_BODY || {};

/* ==================== الشرايين والدهون والضغط ==================== */

DX_BODY['dyslipidemia'] = {
  symptoms: {
    ar: 'لا يشعر به صاحبه إطلاقاً، وهذا هو جوهر المشكلة. لا ألم ولا تعب ولا علامة تنبّه، والرقم وحده هو الذي يتكلّم في ورقة التحليل. أغلب الناس يكتشفونه في فحص روتيني أو عند التبرّع بالدم أو حين يُفحصون لسبب آخر تماماً، وقد مرّت سنوات والدهون تعمل في جدران الشرايين. وحين يظهر شيء محسوس فغالباً يكون قد ظهر متأخّراً: ألم صدر مع المجهود، أو ألم في بطّة الساق عند المشي، أو جلطة. وفي حالات الارتفاع الوراثي الشديد قد تُرى علامات على الجسم نفسه: ترسّبات دهنية صفراء حول الجفون، أو نتوءات على وتر أخيل أو مفاصل الأصابع، أو حلقة بيضاء حول قرنية العين عند شابّ صغير السنّ — وهذه علامة لا تُهمَل لأنها تعني أن الارتفاع كبير وقديم وفي العائلة.',
    en: 'It is not felt at all, and that is the heart of the problem. There is no pain, no tiredness and no warning sign; only the number on the laboratory sheet speaks. Most people find it at a routine check, when donating blood, or while being tested for something else entirely, after years in which the fats have been at work in the artery walls. When something is finally felt it is usually late: chest pain on exertion, calf pain on walking, or a clot. In severe inherited forms there may be signs on the body itself: yellow fatty deposits around the eyelids, lumps on the Achilles tendon or finger knuckles, or a white ring around the cornea in a young person — a sign not to be ignored, because it means the level is high, long-standing and runs in the family.'
  },
  cause: {
    ar: 'الكوليسترول ليس عدواً في ذاته: الجسم يصنعه في الكبد ويحتاجه لبناء أغشية الخلايا وصناعة الهرمونات والصفراء. المشكلة في توازن ناقلاته. ناقل يحمل الدهون من الكبد إلى الأنسجة، وحين يزيد ويتأكسد يتسلّل إلى جدار الشريان فتلتهمه خلايا المناعة وتتحوّل إلى لويحة عصيدية تضيّق المجرى. وناقل آخر يعمل بالعكس فيلتقط الفائض ويعيده إلى الكبد، وارتفاعه في صالحك. وهناك الدهون الثلاثية التي ترتفع بسرعة مع السكّريات والمشروبات المحلّاة والكحول والسمنة البطنية. وأكثر ما يرفع الأرقام: الغذاء الغنيّ بالدهون المهدرجة والمقليّات، وقلّة الحركة، والسمنة، والتدخين الذي يخفض الناقل النافع. ويقف خلف بعضها سبب طبّي كقصور الدرقية أو مرض الكلى أو السكّري أو بعض الأدوية. ويبقى عامل لا يُغيَّر: استعداد وراثي عائلي قد يرفع الكوليسترول من الطفولة.',
    en: 'Cholesterol is not an enemy in itself: the liver makes it, and the body needs it to build cell membranes and to make hormones and bile. The problem lies in the balance of its carriers. One carrier takes fat from the liver out to the tissues, and when it is high and becomes oxidised it slips into the artery wall, where immune cells swallow it and turn it into a plaque that narrows the channel. Another carrier works the other way, collecting the excess and returning it to the liver, and a high level of it is in your favour. Then there are the triglycerides, which rise quickly with sugars, sweetened drinks, alcohol and central obesity. What raises the numbers most is a diet rich in hydrogenated fat and fried food, inactivity, obesity and smoking, which lowers the helpful carrier. Behind some cases lies a medical cause such as an underactive thyroid, kidney disease, diabetes or certain medicines. And one factor cannot be changed: an inherited family tendency that can raise cholesterol from childhood.'
  },
  diagnosis: {
    ar: 'تحليل دم بسيط يقيس الكوليسترول الكلّي والناقل الضارّ والناقل النافع والدهون الثلاثية. لم يعد الصيام شرطاً في أغلب الحالات، لكن الطبيب قد يطلبه إذا كانت الدهون الثلاثية مرتفعة جداً لأنها تتأثّر بالوجبة الأخيرة أكثر من غيرها. والرقم وحده لا يعني شيئاً بلا سياقه: الطبيب لا يعالج رقماً بل يقدّر خطرك الكلّي على السنوات العشر القادمة بجمع العمر والجنس والتدخين وضغط الدم والسكّري والتاريخ العائلي مع نتيجة التحليل، وهذا ما يقرّر هل تكفي تغييرات الحياة أم يلزم الدواء. ويُطلب معه فحص السكّر ووظائف الدرقية والكلى والكبد لاستبعاد سبب قابل للعلاج. وعند الشكّ في خطر عالٍ قد يُضاف تصوير الشريان السباتي بالموجات الصوتية لقياس سماكة جداره، أو أشعة مقطعية تحسب الكالسيوم المترسّب في الشرايين التاجية، وكلاهما يترجم الرقم إلى صورة يراها المريض.',
    en: 'A simple blood test measuring total cholesterol, the harmful carrier, the helpful carrier and the triglycerides. Fasting is no longer required in most cases, though the doctor may ask for it if the triglycerides are very high, since they are affected by the last meal more than the rest. The number alone means nothing without its context: the doctor does not treat a number but estimates your total risk over the coming ten years, combining age, sex, smoking, blood pressure, diabetes and family history with the result, and it is this that decides whether lifestyle changes are enough or medication is needed. Tests of sugar, thyroid, kidney and liver are taken with it to exclude a treatable cause. Where high risk is suspected, an ultrasound of the carotid artery may be added to measure the thickness of its wall, or a CT scan to count the calcium deposited in the coronary arteries — both turning a number into a picture the patient can see.'
  },
  treatment: {
    ar: 'الأساس تغيير يدوم لا حمية شهر: تقليل الدهون المهدرجة والمقليّات واللحوم المصنّعة، وزيادة الخضار والبقول والحبوب الكاملة والأسماك، واستبدال الزيوت النباتية الجيدة بالدهون الصلبة، وتقليل السكّريات والمشروبات المحلّاة لأنها أقوى ما يرفع الدهون الثلاثية. ويُضاف إليها نشاط هوائي منتظم أغلب أيام الأسبوع، وإنقاص الوزن ولو قليلاً فأثره على الأرقام أكبر ممّا يُتوقّع، وإقلاع تامّ عن التدخين. فإن بقي الخطر عالياً وصف الطبيب دواءً يخفض تصنيع الكوليسترول في الكبد أو يقلّل امتصاصه من الأمعاء، ويختار قوّته بحسب خطرك لا بحسب الرقم وحده، ويتابع بتحليل دوري لوظائف الكبد. والخطأ الشائع أن يتوقّف الناس عن الدواء حين تتحسّن الأرقام، والأرقام تحسّنت بسببه — القرار بالإيقاف أو التخفيف للطبيب وحده.',
    en: 'The foundation is a lasting change, not a month of dieting: less hydrogenated fat, fried food and processed meat; more vegetables, pulses, whole grains and fish; good vegetable oils in place of solid fats; and fewer sugars and sweetened drinks, which raise triglycerides more than anything else. To this are added regular aerobic activity on most days of the week, weight loss — even a modest amount has a greater effect on the numbers than expected — and complete cessation of smoking. If the risk remains high, the doctor prescribes a medicine that reduces the liver’s production of cholesterol or its absorption from the gut, choosing its strength according to your risk rather than the number alone, and following it with periodic liver tests. A common mistake is to stop the medicine once the numbers improve, when it is the medicine that improved them: the decision to stop or reduce belongs to the doctor alone.'
  },
  seeDoctor: {
    ar: 'هذا مرض لا يُكتشف إلا بالتحليل، فاطلبه ولا تنتظر عرضاً: ابدأ الفحص في العشرينات إذا كان في العائلة جلطة قلبية أو سكتة مبكّرة أو ارتفاع كوليسترول وراثي، وكرّره كل بضع سنوات إن كان طبيعياً وسنوياً إن كنت مصاباً بالسكّري أو الضغط أو مدخّناً أو زائد الوزن. واحجز موعداً قريباً لا مؤجّلاً إذا رأيت ترسّبات صفراء حول الجفون أو حلقة بيضاء حول القرنية قبل الأربعين، أو إذا كانت الدهون الثلاثية مرتفعة جداً في التحليل لأنها قد تُشعل التهاب البنكرياس. واتصل بالإسعاف فوراً — لأن الأرقام ليست هي الخطر بل ما تصنعه — إذا جاءك ضغط أو ألم في وسط الصدر يستمرّ أكثر من بضع دقائق، أو ضعف مفاجئ في جهة من الجسم أو تلعثم أو ميلان في الوجه.',
    en: 'This is a disease found only by testing, so ask for the test and do not wait for a symptom: start in your twenties if the family has had an early heart attack or stroke or inherited high cholesterol, repeat it every few years if normal and yearly if you have diabetes, high blood pressure, smoke or carry extra weight. Book an early appointment if you see yellow deposits around the eyelids or a white ring around the cornea before the age of forty, or if the triglycerides are very high, since they can set off inflammation of the pancreas. Call an ambulance at once if pressure or pain in the middle of the chest lasts more than a few minutes, or if there is sudden weakness on one side of the body, slurred speech or a drooping face.'
  },
  updated: '2026-09-08'
};

DX_BODY['hypotension'] = {
  symptoms: {
    ar: 'الإحساس المميّز يأتي في الثواني الأولى بعد الوقوف من الجلوس أو من السرير: دوخة، وسواد أو ضبابية أمام العين، وطنين، وثقل في الرأس، وأحياناً غثيان أو تعرّق بارد، ثم يزول كلّ ذلك خلال ثوانٍ إذا جلست أو استندت. وبعض الناس لا يصلون إلى الجلوس فيسقطون مغشيّاً عليهم. ويشتدّ العرض في الصباح الباكر، وبعد وجبة دسمة، وفي الجوّ الحارّ، وبعد حمّام ساخن، وعند الوقوف الطويل في طابور أو صلاة. ومن الناس من ضغطه منخفض دائماً بلا أي شكوى وهذا ليس مرضاً ولا يحتاج علاجاً. أما إذا صحب الهبوط شحوب شديد وبرودة أطراف ونبض سريع ضعيف وتشوّش وعي، فهذه ليست دوخة وقوف بل صورة نقص حادّ في الدورة الدموية تحتاج إسعافاً.',
    en: 'The characteristic feeling comes in the first seconds after standing up from a chair or a bed: dizziness, greying or blurring of vision, ringing in the ears, heaviness in the head, sometimes nausea or a cold sweat, all of it clearing within seconds if you sit or lean on something. Some people do not reach a seat and faint. It is worse early in the morning, after a heavy meal, in hot weather, after a hot shower, and on standing for a long time in a queue or in prayer. Some people simply have a low reading all the time with no complaint at all, and that is not a disease and needs no treatment. But if the drop comes with marked pallor, cold limbs, a fast weak pulse and clouded awareness, this is no longer standing dizziness but a picture of acute circulatory failure needing emergency care.'
  },
  cause: {
    ar: 'حين تقف ينزل نحو نصف لتر من الدم إلى ساقيك بفعل الجاذبية، والمفروض أن يردّ الجهاز العصبي الذاتي في ثانية واحدة: يقبض الأوعية ويسرّع النبض فيثبت الضغط. الأعراض تظهر حين يتأخّر هذا الردّ أو يضعف. وأشيع أسبابه نقص السوائل: قلّة الشرب، والعرق في الحرّ، والإسهال والقيء، والحمّى. ثم الأدوية وهي سبب كبير يُنسى: خافضات الضغط ومدرّات البول وأدوية البروستاتا وبعض أدوية الاكتئاب والنوم، خاصةً عند كبار السنّ الذين يأخذون عدّة أدوية معاً. ويضعف الردّ نفسه في السكّري المزمن وباركنسون وأمراض الأعصاب الذاتية. وقد يكون السبب في القلب: بطء شديد أو تسارع أو ضيق صمّام أو ضعف عضلة. ومنه ما يرتبط بالغدد كقصور الكظر، أو بفقر دم شديد أو نزف داخلي خفيّ. وأشيع صورة عند الشباب هي الإغماء الوعائي المبهمي بعد وقوف طويل أو ألم أو منظر دم.',
    en: 'When you stand, gravity drops about half a litre of blood into your legs, and the autonomic nervous system is meant to answer within a second by tightening the vessels and quickening the pulse to hold the pressure steady. Symptoms appear when that answer is late or weak. The commonest cause is lack of fluid: drinking too little, sweating in the heat, diarrhoea, vomiting and fever. Then medicines, a large and forgotten cause: blood pressure drugs, water tablets, prostate medicines and some antidepressants and sleeping aids, especially in older people taking several at once. The response itself weakens in long-standing diabetes, in Parkinson’s disease and in disorders of the autonomic nerves. The cause may lie in the heart: a very slow or very fast rhythm, a narrowed valve or a weak muscle. Some cases relate to the glands, such as adrenal failure, or to severe anaemia or hidden internal bleeding. In young people the commonest picture is a vasovagal faint after long standing, pain or the sight of blood.'
  },
  diagnosis: {
    ar: 'المفتاح قياس الضغط مستلقياً ثم بعد الوقوف مباشرة ثم بعد ثلاث دقائق واقفاً، لأن الهبوط لا يظهر في قياس واحد جالس. ويُقاس النبض مع كلّ قراءة: ارتفاعه مع الهبوط يوحي بنقص سوائل، وثباته يوحي بخلل في الأعصاب الذاتية. ثم يُراجَع كل دواء تأخذه بالورقة لا بالذاكرة، لأن كثيراً من الحالات يُحلّ بتعديل جرعة يقرّره الطبيب. وتُطلب تحاليل دم للهيموغلوبين والأملاح والسكّر ووظائف الكلى والدرقية، وتخطيط للقلب لكشف بطء أو حصار أو تسارع. وإن تكرّر الإغماء أُضيف تسجيل طويل لنظم القلب على مدى يوم أو أكثر، أو اختبار المائدة المائلة الذي يُثبّت المريض على طاولة تُمال تدريجياً لتُستدرج النوبة تحت المراقبة. وعند الشكّ في القلب يُصوَّر بالموجات الصوتية لتقييم الصمّامات وقوّة العضلة.',
    en: 'The key is measuring the pressure lying down, then immediately on standing, then again after three minutes upright, because the drop does not show in a single seated reading. The pulse is taken with every reading: a rise alongside the fall suggests fluid depletion, while an unchanged pulse suggests a fault in the autonomic nerves. Every medicine you take is then reviewed from the packet rather than from memory, since many cases are solved by a dose adjustment the doctor decides. Blood tests are ordered for haemoglobin, salts, sugar, kidney and thyroid function, with an ECG to detect a slow, blocked or fast rhythm. If fainting recurs, a long recording of the heart rhythm over a day or more is added, or a tilt-table test in which the patient is strapped to a table that is gradually tilted to bring on the attack under observation. Where the heart is suspected, an ultrasound assesses the valves and the strength of the muscle.'
  },
  treatment: {
    ar: 'العلاج يبدأ بالسبب لا بالضغط: تعويض السوائل، وعلاج النزف أو فقر الدم، ومراجعة الأدوية مع الطبيب فقد يكفي تعديل موعد جرعة أو خفضها. ثم تدابير بسيطة أثرها كبير: قم من السرير على مراحل واجلس على حافّته دقيقة قبل الوقوف، واشرب ماءً كافياً على مدار اليوم وخاصةً في الحرّ، وتجنّب الوقوف الطويل بلا حركة وحرّك ساقيك في مكانك، وارفع رأس السرير قليلاً، وقلّل الوجبات الدسمة الكبيرة واجعلها صغيرة متعدّدة. وجوارب الضغط المتدرّج تمنع تجمّع الدم في الساقين. وإن أحسست ببداية النوبة فاجلس أو استلقِ فوراً وارفع ساقيك، أو شدّ عضلات ساقيك وقبضتيك بقوّة، فهذا يرفع الضغط في ثوانٍ ويمنع السقطة. وفي الحالات المستمرّة قد يصف الطبيب دواءً يرفع الضغط أو يحبس الملح والماء، وقد يزيد ملح الطعام في نظامك — وهذا قرار طبّي لا يُتّخذ ذاتياً خاصةً مع قصور القلب.',
    en: 'Treatment starts with the cause, not with the pressure: replacing fluid, treating bleeding or anaemia, and reviewing medicines with the doctor, since shifting or lowering a dose may be enough. Then simple measures with a large effect: get out of bed in stages and sit on its edge for a minute before standing; drink enough water through the day, especially in the heat; avoid standing still for long and keep the legs moving on the spot; raise the head of the bed a little; and replace large heavy meals with smaller frequent ones. Graduated compression stockings stop blood pooling in the legs. If you feel an attack beginning, sit or lie down at once and raise your legs, or tense the leg and fist muscles hard, which lifts the pressure within seconds and prevents the fall. In persistent cases the doctor may prescribe a medicine that raises the pressure or holds salt and water, and may increase dietary salt — a medical decision, never one to take alone, especially with heart failure.'
  },
  seeDoctor: {
    ar: 'اتصل بالإسعاف فوراً إذا صاحب الهبوط ألم في الصدر أو ضيق نفس شديد، أو نزف واضح أو قيء دموي أو براز أسود، أو ارتباك ولم يستعد وعيه خلال دقيقة، أو أُغمي عليه وهو يبذل مجهوداً أو مستلقياً — فالإغماء أثناء الجهد قد يعني مشكلة في الصمّام أو النظم لا مجرّد دوخة وقوف. واذهب للطوارئ إذا كان الجلد بارداً رطباً والنبض سريعاً ضعيفاً، أو مع حمّى وارتباك. واحجز موعداً قريباً إذا تكرّر الإغماء، أو بدأ الهبوط بعد دواء جديد، أو صحبه تنميل الأطراف أو جفاف الفم أو ضعف الانتصاب فقد تكون أعصاب الجسم الذاتية متأثّرة، أو إذا سقطت وأنت كبير في السنّ ولو مرّة. أما دوخة خفيفة عابرة عند الوقوف السريع وتزول في ثوانٍ فلا تستدعي قلقاً.',
    en: 'Call an ambulance at once if the drop comes with chest pain or severe breathlessness, with obvious bleeding, vomiting of blood or black stools, with confusion or a failure to come round within a minute, or if the faint happened during exertion or while lying down — fainting on effort may mean a valve or rhythm problem rather than simple standing dizziness. Go to emergency if the skin is cold and clammy with a fast weak pulse, or if there is fever and confusion. Book an early appointment if fainting recurs, if the drops began after a new medicine, if there is also numbness of the limbs, a dry mouth or erectile difficulty suggesting the autonomic nerves are affected, or if you are older and have fallen even once. Brief dizziness on standing quickly that clears in seconds needs no alarm.'
  },
  updated: '2026-09-08'
};

